from pathlib import Pathimport numpy as npimport pandas as pdROOT = Path(__file__).resolve().parent.parentSOURCE = ROOT / "data/processed/multisat_2024_recent_daily_decay_kp.csv"OUTPUT = ROOT / "results/multisat_2024_orbital_behavior.csv"df = pd.read_csv(SOURCE)df["date"] = pd.to_datetime(df["date"], utc=True)df["decay_km_day"] = pd.to_numeric(    df["decay_km_day"], errors="coerce")# Net altitude change per day is the negative# of the calculated decay rate.df["altitude_change_km_day"] = -df["decay_km_day"]THRESHOLD = 0.2  # km/dayMIN_DAYS = 5CONSISTENCY = 0.70results = []for norad_id, group in df.groupby("norad_id"):    group = group.sort_values("date")    changes = group["altitude_change_km_day"].dropna()    n = len(changes)    if n == 0:        behavior = "Insufficient data"        median_change = np.nan        raising_fraction = np.nan        lowering_fraction = np.nan    else:        median_change = changes.median()        raising_fraction = (changes > THRESHOLD).mean()        lowering_fraction = (changes < -THRESHOLD).mean()        if n < MIN_DAYS:            behavior = "Insufficient data"        elif raising_fraction >= CONSISTENCY:            behavior = "Sustained orbit raising candidate"        elif lowering_fraction >= CONSISTENCY:            behavior = "Sustained orbit lowering candidate"        elif (changes.abs() <= THRESHOLD).mean() >= CONSISTENCY:            behavior = "Relatively stable"        else:            behavior = "Mixed orbital behavior"    results.append({        "norad_id": norad_id,        "satellite_name": group["satellite_name"].iloc[0],        "altitude_band": group["altitude_band"].iloc[0],        "n_days": n,        "median_altitude_change_km_day": median_change,        "raising_fraction": raising_fraction,        "lowering_fraction": lowering_fraction,        "behavior": behavior    })result = pd.DataFrame(results)result.to_csv(OUTPUT, index=False)print("\nORBITAL BEHAVIOR CATEGORIES:")print(result["behavior"].value_counts().to_string())print("\nBY ALTITUDE BAND:")print(    pd.crosstab(        result["altitude_band"],        result["behavior"]    ).to_string())print("\nSTARLINK-31725:")print(    result[result["norad_id"] == 59538].to_string(index=False))print(f"\nSaved: {OUTPUT}")